function gradientDescent(objective, gradient, theta, eta, stop):
  require compatibleLengths(theta,eta)
  for iteration in 0..stop.maxIterations-1:
    value = objective(theta)
    g = gradient(theta)
    require finite(value,g)
    next = theta - componentwise(eta * g)
    nextValue = objective(next)
    require finite(next,nextValue)
    if stopSatisfied(theta,next,value,nextValue,g,stop):
      return {theta:next,value:nextValue,iterations:iteration+1}
    theta = next
  return {theta,value:objective(theta),status:'MAX_ITERATIONS'}

function newton(f, df, x, stop):
  require stop.maxIterations > 0 and stop.tolerance > 0
  for i in 0..stop.maxIterations-1:
    fx = f(x); dfx = df(x)
    require finite(fx,dfx)
    if abs(fx) <= stop.tolerance: return {root:x,status:'CONVERGED'}
    if abs(dfx) <= stop.derivativeFloor: return {root:x,status:'ZERO_DERIVATIVE'}
    delta = -fx/dfx
    next = x + delta
    require finite(next)
    if abs(delta) <= stop.stepTolerance: return {root:next,status:'STEP_SMALL'}
    x = next
  return {root:x,status:'MAX_ITERATIONS'}

function bisection(f,a,b,tol,maxIterations):
  require finite(a,b,tol) and a < b and tol > 0
  fa=f(a); fb=f(b)
  require finite(fa,fb) and fa*fb <= 0
  if fa == 0: return {root:a,status:'ENDPOINT'}
  if fb == 0: return {root:b,status:'ENDPOINT'}
  for i in 0..maxIterations-1:
    if (b-a)/2 <= tol: return {root:(a+b)/2,interval:[a,b],status:'CONVERGED'}
    m=(a+b)/2; fm=f(m)
    require finite(fm)
    if fm == 0: return {root:m,status:'EXACT'}
    if sign(fa) != sign(fm): b=m; fb=fm
    else: a=m; fa=fm
  return {root:(a+b)/2,interval:[a,b],status:'MAX_ITERATIONS'}

function fourierSeries(signal, period, harmonics, integrate):
  require finite(period) and period > 0 and harmonics >= 0
  omega = 2*pi/period
  a0 = (1/period) * integrate(signal,0,period)
  for n in 1..harmonics:
    an = (2/period) * integrate(t => signal(t)*cos(n*omega*t),0,period)
    bn = (2/period) * integrate(t => signal(t)*sin(n*omega*t),0,period)
  return {a0,an,bn,omega}

function continuousWaveletTransform(signal, psi, scales, shifts, integrate):
  require all(scales != 0) and finite(scales,shifts)
  for a in scales:
    for b in shifts:
      coefficient = integrate(t => signal(t)*conjugate(psi((t-b)/a))/sqrt(abs(a)), domain)
      require finite(coefficient)
      W[a,b] = coefficient
  return W

function blueNoiseSample(domain,rMin,targetCount,spectralCriterion,budget,rng):
  require valid(domain) and rMin > 0 and targetCount > 0 and budget > 0
  points = []
  for attempt in 1..budget:
    candidate = sampleUniform(domain,rng)
    if all(distance(candidate,p) >= rMin for p in points):
      points.append(candidate)
    if length(points) == targetCount: break
  spectrum = structureFactor(points)
  status = spectralCriterion(spectrum) ? 'CRITERION_MET' : 'BUDGET_OR_CANDIDATES_EXHAUSTED'
  return {points,spectrum,status}
